def teams_to_entries(apps, schema_editor):
    """Existing tournaments: their teams become invited teams of their final stage."""
    Tournament = apps.get_model("tournaments", "Tournament")
    Entry = apps.get_model("tournaments", "Entry")
    Stage = apps.get_model("league", "Stage")
    for t in Tournament.objects.all():
        final = Stage.objects.filter(season_id=t.season_id).order_by("-order", "-pk").first()
        if final is None:
            continue
        for team in t.teams.all():
            Entry.objects.get_or_create(
                tournament=t, stage=final, team=team, defaults={"via": "INVITED", "status": "IN"}
            )


Migration.operations.append(migrations.RunPython(teams_to_entries, migrations.RunPython.noop))
